create table if not exists public.ils_professional_security_execution_audit (id uuid primary key default gen_random_uuid(),binding_id uuid not null references public.ils_professional_security_approval_execution_bindings(id),queue_id uuid not null,approval_log_id uuid not null,approved_action text not null,execution_nonce text not null,approval_snapshot_hash text not null,event_type text not null check(event_type in ('BOUND','EXECUTION_ACCEPTED','EXECUTION_BLOCKED','EXECUTED','EXPIRED','CANCELLED','REPLAY_BLOCKED')),decision text not null check(decision in ('ALLOW','BLOCK')),reason_code text not null,previous_event_hash text,event_hash text not null unique,occurred_at timestamptz not null default now()); alter table public.ils_professional_security_execution_audit enable row level security; alter table public.ils_professional_security_execution_audit force row level security; revoke all on public.ils_professional_security_execution_audit from anon,authenticated; create index if not exists ils_professional_security_execution_audit_binding_idx on public.ils_professional_security_execution_audit(binding_id,occurred_at); create unique index if not exists ils_professional_security_execution_audit_nonce_event_idx on public.ils_professional_security_execution_audit(execution_nonce,event_type); create table if not exists public.ils_professional_security_execution_audit_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_execution_audit_tests enable row level security; alter table public.ils_professional_security_execution_audit_tests force row level security; revoke all on public.ils_professional_security_execution_audit_tests from anon,authenticated; insert into public.ils_professional_security_execution_audit_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('BIND_RECEIPT','RECEIPT','RECEIPT',true,'Every valid binding can have a tamper-evident audit receipt.'),('ACCEPT_RECEIPT','RECEIPT','RECEIPT',true,'Accepted execution context is auditable.'),('BLOCK_RECEIPT','RECEIPT','RECEIPT',true,'Blocked execution attempts are auditable.'),('EXECUTED_RECEIPT','RECEIPT','RECEIPT',true,'Successful execution is auditable.'),('REPLAY_RECEIPT','RECEIPT','RECEIPT',true,'Replay blocks are auditable.'),('HASH_CHAIN','REQUIRED','REQUIRED',true,'Each event links to the previous event hash.'),('HASH_UNIQUENESS','REQUIRED','REQUIRED',true,'Duplicate event hashes are rejected.'),('NONCE_TRACE','REQUIRED','REQUIRED',true,'Execution nonce links audit events to one authorization.'),('ACTION_TRACE','REQUIRED','REQUIRED',true,'Approved action remains traceable.'),('IMMUTABLE_CLIENT','BLOCK','BLOCK',true,'Direct client access is revoked and RLS is forced.'),('ORDERED_EVENTS','REQUIRED','REQUIRED',true,'Events retain occurred_at ordering.'),('LIVE_E2E','PENDING','PENDING',true,'No live execution exists in TEST; no synthetic execution performed.');